package com.example.leetcodetrainer.curriculum.service;
import com.example.leetcodetrainer.curriculum.domain.*; import com.example.leetcodetrainer.curriculum.repository.*; import java.util.*; import java.util.stream.Collectors; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class CurriculumFoundationService { private final SkillDefinitionRepository skills; private final LearningModeDefinitionRepository modes; private final ModeSkillRequirementRepository requirements; private final CurriculumItemRepository items; private final ProblemExposureRepository exposures; private final LearningSessionRepository sessions; public CurriculumFoundationService(SkillDefinitionRepository a,LearningModeDefinitionRepository b,ModeSkillRequirementRepository c,CurriculumItemRepository d,ProblemExposureRepository e,LearningSessionRepository f){skills=a;modes=b;requirements=c;items=d;exposures=e;sessions=f;} public List<SkillDefinition> skills(){return skills.findByActiveTrueOrderByDisplayOrderAsc();} public List<LearningModeDefinition> modes(){return modes.findByActiveTrueOrderByDisplayOrderAsc();} public List<ModeSkillRequirement> requirements(){return requirements.findAllByOrderByLearningModeAscDisplayOrderAsc();} public List<CurriculumItem> items(){return items.findByActiveTrueOrderByDisplayOrderAsc();} public List<ProblemExposure> exposures(){return exposures.findAllByOrderByUpdatedAtDesc();} public List<LearningSession> sessions(){return sessions.findAllByOrderByCreatedAtDesc();} public Map<CurriculumRole,Long> coverageByRole(){return items().stream().collect(Collectors.groupingBy(CurriculumItem::getRole, LinkedHashMap::new, Collectors.counting()));} public Map<UUID,Long> coverageByPattern(){return items().stream().collect(Collectors.groupingBy(CurriculumItem::getPatternId, LinkedHashMap::new, Collectors.counting()));} public boolean isHoldoutEligible(CurriculumItem item, ProblemExposure exposure){return item.isHoldoutEligible(exposure);} }
